def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    last_m, last_o = history[-1]

    if n == 99:
        return 'D'

    if my_defects > 0 and opp_defects == 0:
        retaliation = False
        has_completed_defection = False
        for i in range(n - 1):
            if history[i][0] == 'D':
                has_completed_defection = True
                if history[i + 1][1] == 'D':
                    retaliation = True
                    break
        if retaliation:
            return 'C'
        else:
            if has_completed_defection:
                return 'D'
            else:
                return 'C'

    if opp_defects == 0 and my_defects == 0:
        if n == 1:
            return 'D'
        return 'D'

    if n < 10 and my_defects == 0:
        if last_o == 'D':
            return 'D'
        return 'C'

    if n > 90:
        if opp_defects <= 2:
            return 'C'

    if last_o == 'C':
        return 'C'

    if n < 30:
        if opp_defects <= max(1, n // 10):
            return 'C'
        return 'D'

    if opp_defects > n * 0.3:
        return 'D'

    if opp_defects > n * 0.15:
        if last_m == 'D' and last_o == 'D':
            if n >= 2 and history[-2][1] == 'D':
                return 'C'
        return 'D'

    return 'C'
